   hours: document.getElementById("hours"),
   minutes: document.getElementById("minutes"),
   seconds: document.getElementById("seconds"),
 };

 function pad(value) {
   return String(value).padStart(2, "0");
 }

 function updateCountdown() {
   const difference = launchDate.getTime() - Date.now();
   const remaining = Math.max(0, difference);

   const days = Math.floor(remaining / (1000 * 60 * 60 * 24));
   const hours = Math.floor((remaining / (1000 * 60 * 60)) % 24);
   const minutes = Math.floor((remaining / (1000 * 60)) % 60);
   const seconds = Math.floor((remaining / 1000) % 60);

   countdownNodes.days.textContent = pad(days);
   countdownNodes.hours.textContent = pad(hours);
   countdownNodes.minutes.textContent = pad(minutes);
   countdownNodes.seconds.textContent = pad(seconds);
 }

 const productGrid = document.querySelector(".product-grid");
 const shuffleButton = document.getElementById("shuffle-products");

 shuffleButton.addEventListener("click", () => {
   const products = Array.from(productGrid.children);

   products
     .sort(() => Math.random() - 0.5)
     .forEach((product) => productGrid.appendChild(product));
 });

 updateCountdown();
 window.setInterval(updateCountdown, 1000);

